PRAGMA foreign_keys=ON;
CREATE TABLE platforms(id TEXT PRIMARY KEY,name TEXT NOT NULL);
INSERT INTO platforms VALUES('ctrip','携程');
CREATE TABLE devices(id TEXT PRIMARY KEY,credential_hash TEXT NOT NULL,name TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','disabled')),created_at TEXT NOT NULL,approved_at TEXT,last_seen_at TEXT,last_error TEXT,version TEXT,supported_platforms TEXT NOT NULL DEFAULT '["ctrip"]');
CREATE INDEX devices_status_seen ON devices(status,last_seen_at);
CREATE TABLE plans(id TEXT PRIMARY KEY,platform TEXT NOT NULL REFERENCES platforms(id),city TEXT NOT NULL,keyword TEXT NOT NULL,scope TEXT NOT NULL CHECK(scope IN ('top30','custom','all')),collection_limit INTEGER,horizon INTEGER NOT NULL CHECK(horizon IN(14,30)),enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE tasks(id TEXT PRIMARY KEY,plan_id TEXT REFERENCES plans(id),schedule_key TEXT UNIQUE,platform TEXT NOT NULL REFERENCES platforms(id),city TEXT NOT NULL,keyword TEXT NOT NULL,checkin TEXT NOT NULL,checkout TEXT NOT NULL,scope TEXT NOT NULL CHECK(scope IN('top30','custom','all')),collection_limit INTEGER,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','RUNNING','COMPLETED','PARTIAL','FAILED')),preferred_device_id TEXT REFERENCES devices(id),created_at TEXT NOT NULL,due_at TEXT NOT NULL,window_start TEXT NOT NULL,window_end TEXT NOT NULL,finished_at TEXT,error_code TEXT,error_message TEXT,market_status TEXT,detail_success INTEGER,detail_total INTEGER,capacity_warning INTEGER NOT NULL DEFAULT 0,CHECK(window_start<window_end),CHECK(checkin<checkout),CHECK((scope='all' AND collection_limit IS NULL) OR (scope='top30' AND collection_limit=30) OR (scope='custom' AND collection_limit>0)));
CREATE INDEX tasks_pool ON tasks(status,due_at,window_end);
CREATE INDEX tasks_market ON tasks(platform,city,keyword,checkin,scope,finished_at);
CREATE TABLE attempts(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),attempt_number INTEGER NOT NULL CHECK(attempt_number BETWEEN 1 AND 5),device_id TEXT NOT NULL REFERENCES devices(id),claimed_at TEXT NOT NULL,started_at TEXT,finished_at TEXT,timeout_at TEXT NOT NULL,lease_until TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('RUNNING','COMPLETED','PARTIAL','FAILED')),error_code TEXT,error_message TEXT,returned_to_queue_at TEXT,core_hotels TEXT NOT NULL DEFAULT '[]',UNIQUE(task_id,attempt_number));
CREATE UNIQUE INDEX one_running_per_device ON attempts(device_id) WHERE status='RUNNING';
CREATE UNIQUE INDEX one_running_per_task ON attempts(task_id) WHERE status='RUNNING';
CREATE INDEX attempts_timeout ON attempts(status,lease_until,timeout_at);
CREATE TABLE attempt_events(id INTEGER PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),attempt_id TEXT NOT NULL REFERENCES attempts(id),device_id TEXT NOT NULL REFERENCES devices(id),at TEXT NOT NULL,event TEXT NOT NULL,code TEXT,message TEXT);
CREATE INDEX attempt_events_timeline ON attempt_events(attempt_id,at);
CREATE TABLE platform_hotels(platform TEXT NOT NULL REFERENCES platforms(id),hotel_id TEXT NOT NULL,original_name TEXT NOT NULL,first_seen_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,PRIMARY KEY(platform,hotel_id));
CREATE TABLE livv_hotels(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'other' CHECK(category IN('mine','core','competitor','watch','other')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX single_my_hotel ON livv_hotels(category) WHERE category='mine';
CREATE TABLE hotel_mappings(platform TEXT NOT NULL,hotel_id TEXT NOT NULL,livv_hotel_id TEXT NOT NULL REFERENCES livv_hotels(id),confirmed_at TEXT NOT NULL,confirmed_by TEXT NOT NULL,PRIMARY KEY(platform,hotel_id),FOREIGN KEY(platform,hotel_id) REFERENCES platform_hotels(platform,hotel_id));
CREATE TABLE mapping_history(id INTEGER PRIMARY KEY,platform TEXT NOT NULL,hotel_id TEXT NOT NULL,livv_hotel_id TEXT NOT NULL REFERENCES livv_hotels(id),action TEXT NOT NULL CHECK(action IN('link','unlink')),at TEXT NOT NULL,actor TEXT NOT NULL);
CREATE TABLE snapshots(id TEXT PRIMARY KEY,task_id TEXT NOT NULL UNIQUE REFERENCES tasks(id),attempt_id TEXT NOT NULL UNIQUE REFERENCES attempts(id),device_id TEXT NOT NULL REFERENCES devices(id),observed_at TEXT NOT NULL,received_at TEXT NOT NULL,exhausted INTEGER NOT NULL,stop_reason TEXT NOT NULL,payload_hash TEXT NOT NULL,market_count INTEGER NOT NULL,market_status TEXT NOT NULL,detail_success INTEGER NOT NULL,detail_total INTEGER NOT NULL,detail_results TEXT NOT NULL);
CREATE TABLE market_observations(snapshot_id TEXT NOT NULL REFERENCES snapshots(id),platform TEXT NOT NULL,hotel_id TEXT NOT NULL,hotel_name TEXT NOT NULL,rank INTEGER NOT NULL,is_ad INTEGER NOT NULL CHECK(is_ad IN(0,1)),score REAL,dynamic TEXT,activity_tags TEXT,original_price REAL,display_price REAL,PRIMARY KEY(snapshot_id,platform,hotel_id),FOREIGN KEY(platform,hotel_id) REFERENCES platform_hotels(platform,hotel_id));
CREATE INDEX market_hotel_series ON market_observations(platform,hotel_id,snapshot_id);
CREATE TABLE room_observations(id INTEGER PRIMARY KEY,snapshot_id TEXT NOT NULL REFERENCES snapshots(id),platform TEXT NOT NULL,hotel_id TEXT NOT NULL,hotel_name TEXT NOT NULL,room_name TEXT NOT NULL,original_price REAL,display_price REAL,activity_tags TEXT,availability_status TEXT NOT NULL CHECK(availability_status IN('available','sold_out')),sold_out_evidence TEXT,FOREIGN KEY(platform,hotel_id) REFERENCES platform_hotels(platform,hotel_id));
CREATE TABLE market_analyses(id TEXT PRIMARY KEY,snapshot_id TEXT NOT NULL UNIQUE REFERENCES snapshots(id),created_at TEXT NOT NULL,checkin TEXT NOT NULL,scope TEXT NOT NULL,algorithm_version TEXT NOT NULL,recommendation TEXT NOT NULL CHECK(recommendation IN('raise','observe','lower')),reason TEXT NOT NULL,score REAL NOT NULL,facts TEXT NOT NULL,my_price REAL);
CREATE TRIGGER snapshots_guard BEFORE INSERT ON snapshots BEGIN
 SELECT RAISE(ABORT,'UPLOAD_FENCE_REJECTED') WHERE NOT EXISTS(SELECT 1 FROM attempts a JOIN tasks t ON t.id=a.task_id JOIN devices d ON d.id=a.device_id WHERE a.id=NEW.attempt_id AND t.id=NEW.task_id AND d.id=NEW.device_id AND d.status='approved' AND a.status='RUNNING' AND t.status='RUNNING' AND a.timeout_at>NEW.received_at AND a.lease_until>NEW.received_at AND t.window_end>NEW.received_at AND NEW.observed_at>=a.started_at AND NEW.observed_at<t.window_end AND NEW.observed_at<=NEW.received_at) ;
END;
CREATE TRIGGER snapshot_immutable BEFORE UPDATE ON snapshots BEGIN SELECT RAISE(ABORT,'IMMUTABLE_SNAPSHOT'); END;
CREATE TRIGGER observation_immutable BEFORE UPDATE ON market_observations BEGIN SELECT RAISE(ABORT,'IMMUTABLE_OBSERVATION'); END;
CREATE TRIGGER room_immutable BEFORE UPDATE ON room_observations BEGIN SELECT RAISE(ABORT,'IMMUTABLE_OBSERVATION'); END;
CREATE TRIGGER analysis_immutable BEFORE UPDATE ON market_analyses BEGIN SELECT RAISE(ABORT,'IMMUTABLE_ANALYSIS'); END;
CREATE TRIGGER livv_id_immutable BEFORE UPDATE OF id ON livv_hotels BEGIN SELECT RAISE(ABORT,'IMMUTABLE_HOTEL_ID'); END;
CREATE TRIGGER device_id_immutable BEFORE UPDATE OF id ON devices BEGIN SELECT RAISE(ABORT,'IMMUTABLE_DEVICE_ID'); END;
